func:
// Run state
// 600: 0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault

msg.baseAddr = 600;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 600,
    quantity: 1
};
return msg;

// Warning and Fault words
// 653: Warning message word 1
// 654: Warning message word 2
// 655: Fault information word 1
// 656: Fault information word 2
// 657: Fault information word 3
// 658: Fault information word 4

msg.baseAddr = 653;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 653,
    quantity: 6  // 653-658
};
return msg;

// Build InverterAlarmState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterAlarmState: missing base address");
    return null;
}

// ---- Store partials ----

// RunState 600
if (baseAddr === 600) {
    flow.set("ias_part_runstate", {
        runStateRaw: data[0] || 0
    });
}

// Warnings/Faults 653-658
else if (baseAddr === 653) {
    flow.set("ias_part_warnings_faults", {
        warningWord1Raw: data[0] || 0,   // 653
        warningWord2Raw: data[1] || 0,   // 654
        faultWord1Raw: data[2] || 0,     // 655
        faultWord2Raw: data[3] || 0,     // 656
        faultWord3Raw: data[4] || 0,     // 657
        faultWord4Raw: data[5] || 0      // 658
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const runstatePart = flow.get("ias_part_runstate");
const warningsFaultsPart = flow.get("ias_part_warnings_faults");

if (!runstatePart || !warningsFaultsPart) {
    return null;
}

const gatewayId = msg.gatewayId
    || global.get("GATEWAY_ID")
    || env.get("GATEWAY_ID")
    || "EC100";

const inverterSerial = msg.inverterSerialNumber
    || global.get("INVERTER_SERIAL")
    || env.get("INVERTER_SERIAL")
    || "Unknown";

// Decode active alarms from fault/warning words
const activeAlarms = [];
const now = new Date().toISOString();

// Three-phase Fault Word 1 (655) bit definitions
const faultWord1Bits = {
    0: { code: 1001, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "DC_VOLTAGE_HIGH" },
    1: { code: 1002, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_HIGH" },
    2: { code: 1003, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_LOW" },
    3: { code: 1004, severity: "fault", sourceDevice: "inverter", category: "dc_voltage", messageKey: "BUS_VOLTAGE_UNBALANCED" },
    4: { code: 1005, severity: "fault", sourceDevice: "grid", category: "ac_voltage", messageKey: "GRID_VOLTAGE_HIGH" },
    5: { code: 1006, severity: "fault", sourceDevice: "grid", category: "ac_voltage", messageKey: "GRID_VOLTAGE_LOW" },
    6: { code: 1007, severity: "fault", sourceDevice: "grid", category: "frequency", messageKey: "GRID_FREQ_HIGH" },
    7: { code: 1008, severity: "fault", sourceDevice: "grid", category: "frequency", messageKey: "GRID_FREQ_LOW" },
    8: { code: 1009, severity: "fault", sourceDevice: "grid", category: "connection", messageKey: "GRID_DISCONNECT" },
    9: { code: 1010, severity: "fault", sourceDevice: "inverter", category: "current", messageKey: "OUTPUT_CURRENT_HIGH" },
    10: { code: 1011, severity: "fault", sourceDevice: "inverter", category: "over_temp", messageKey: "INVERTER_OVER_TEMP" },
    11: { code: 1012, severity: "fault", sourceDevice: "inverter", category: "leakage", messageKey: "LEAKAGE_CURRENT_HIGH" },
    12: { code: 1013, severity: "fault", sourceDevice: "inverter", category: "hardware", messageKey: "HARDWARE_FAULT" },
    13: { code: 1014, severity: "fault", sourceDevice: "inverter", category: "communication", messageKey: "EEPROM_FAULT" },
    14: { code: 1015, severity: "fault", sourceDevice: "inverter", category: "relay", messageKey: "RELAY_FAULT" },
    15: { code: 1016, severity: "fault", sourceDevice: "inverter", category: "hardware", messageKey: "DSP_FAULT" }
};

// Three-phase Warning Word 1 (653) bit definitions
const warningWord1Bits = {
    0: { code: 2001, severity: "warning", sourceDevice: "battery", category: "voltage", messageKey: "BATTERY_VOLTAGE_HIGH" },
    1: { code: 2002, severity: "warning", sourceDevice: "battery", category: "voltage", messageKey: "BATTERY_VOLTAGE_LOW" },
    2: { code: 2003, severity: "warning", sourceDevice: "battery", category: "communication", messageKey: "BATTERY_COMM_FAIL" },
    3: { code: 2004, severity: "warning", sourceDevice: "inverter", category: "over_temp", messageKey: "INVERTER_TEMP_HIGH" },
    4: { code: 2005, severity: "warning", sourceDevice: "pv", category: "voltage", messageKey: "PV_VOLTAGE_HIGH" },
    5: { code: 2006, severity: "warning", sourceDevice: "inverter", category: "fan", messageKey: "FAN_LOCKED" },
    6: { code: 2007, severity: "warning", sourceDevice: "grid", category: "power", messageKey: "FEED_IN_POWER_LIMIT" },
    7: { code: 2008, severity: "warning", sourceDevice: "inverter", category: "firmware", messageKey: "FIRMWARE_UPDATE" },
    8: { code: 2009, severity: "warning", sourceDevice: "grid", category: "phase_balance", messageKey: "PHASE_IMBALANCE" },
    9: { code: 2010, severity: "warning", sourceDevice: "inverter", category: "phase_voltage", messageKey: "PHASE_VOLTAGE_UNBALANCED" }
};

// Decode fault bits
function decodeBits(word, bitDefs) {
    const alarms = [];
    for (let bit = 0; bit < 16; bit++) {
        if ((word & (1 << bit)) !== 0 && bitDefs[bit]) {
            const def = bitDefs[bit];
            alarms.push({
                code: def.code,
                vendorCode: bit,
                severity: def.severity,
                sourceDevice: def.sourceDevice,
                category: def.category,
                messageKey: def.messageKey,
                messageParams: {},
                firstOccurredUtc: now,
                lastOccurredUtc: now,
                occurrenceCount: 1
            });
        }
    }
    return alarms;
}

// Decode all words
activeAlarms.push(...decodeBits(warningsFaultsPart.faultWord1Raw, faultWord1Bits));
activeAlarms.push(...decodeBits(warningsFaultsPart.warningWord1Raw, warningWord1Bits));
// Add more decoders for faultWord2-4, warningWord2 as needed

const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSerial,

    runStateRaw: runstatePart.runStateRaw,
    warningWord1Raw: warningsFaultsPart.warningWord1Raw,
    warningWord2Raw: warningsFaultsPart.warningWord2Raw,
    faultWord1Raw: warningsFaultsPart.faultWord1Raw,
    faultWord2Raw: warningsFaultsPart.faultWord2Raw,
    faultWord3Raw: warningsFaultsPart.faultWord3Raw,
    faultWord4Raw: warningsFaultsPart.faultWord4Raw,

    activeAlarms: activeAlarms
};

// Clear partials
flow.set("ias_part_runstate", null);
flow.set("ias_part_warnings_faults", null);

flow.set("inverterAlarmStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Only send to ThingsBoard if there's an actual problem:
// 1. runState != 2 (not normal)
// 2. OR any fault word != 0
// 3. OR any warning word != 0
// 4. OR activeAlarms array has items

const state = msg.payload;

const runStateNormal = state.runStateRaw === 2;
const noFaults = state.faultWord1Raw === 0 && 
                 state.faultWord2Raw === 0 && 
                 state.faultWord3Raw === 0 && 
                 state.faultWord4Raw === 0;
const noWarnings = state.warningWord1Raw === 0 && 
                   state.warningWord2Raw === 0;
const noActiveAlarms = state.activeAlarms.length === 0;

// If everything is normal, don't send
if (runStateNormal && noFaults && noWarnings && noActiveAlarms) {
    // Check if we need to send "all clear" once
    const previousHadAlarm = flow.get("ias_previous_had_alarm") || false;

    if (previousHadAlarm) {
        // Send one "all clear" message
        flow.set("ias_previous_had_alarm", false);
        node.status({ fill: "green", shape: "dot", text: "All clear - sent" });
        return msg;
    } else {
        // Already sent all clear, don't spam
        node.status({ fill: "green", shape: "ring", text: "Normal - skipped" });
        return null;
    }
}

// There's an alarm/warning - send it
flow.set("ias_previous_had_alarm", true);

const alarmCount = state.activeAlarms.length;
const runStateText = {
    0: "standby",
    1: "selfcheck",
    2: "normal",
    3: "ALARM",
    4: "FAULT"
}[state.runStateRaw] || "unknown";

node.status({ 
    fill: state.runStateRaw >= 3 ? "red" : "yellow", 
    shape: "dot", 
    text: `${runStateText} - ${alarmCount} alarms` 
});

return msg;
